const stats = $('Get Daily Stats').first().json;
const topLeads = $('Get Top Hot Leads').all().map(i => i.json);

const today = new Date().toLocaleDateString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

let topLeadsText = '';
if (topLeads.length > 0) {
  topLeadsText = topLeads.map((l, i) => `  ${i+1}. ${l.name} (${l.brand}) - Score: ${l.score}`).join('\n');
} else {
  topLeadsText = '  No hot leads today';
}

const report = `📊 LEADOS DAILY REPORT
${today}

📈 TODAY'S ACTIVITY:
• New Leads: ${stats.new_today || 0}
• Messages Sent: ${stats.messages_today || 0}
• Conversions: ${stats.converted_today || 0}
• Revenue Today: Rs ${parseFloat(stats.revenue_today || 0).toFixed(0)}

🔥 PIPELINE STATUS:
• Total Hot Leads: ${stats.total_hot || 0}
• Total Leads: ${stats.total_leads || 0}
• Month Revenue: Rs ${parseFloat(stats.revenue_month || 0).toFixed(0)}

⭐ TOP HOT LEADS:
${topLeadsText}

🔗 Portal: https://leados-app.abmgroups.org

— LeadOS by ABM Groups`;

return [{ json: { report, stats } }];
